        check("gradePoints('C')", 2.0, GradeLetterMapper.gradePoints('C'));
        check("gradePoints('d') -- lowercase", 1.0, GradeLetterMapper.gradePoints('d'));
        check("gradePoints('f')", 0.0, GradeLetterMapper.gradePoints('f'));
