public class GradeLetterMapper {

    public static char letterFor(int score) {
        if (score < 60) {
            return 'F';
        }
        int band = score / 10;
        if (band > 9) {
            band = 9;
        }
        return (char) ('A' + (9 - band));
    }

    public static double gradePoints(char letter) {
        char upper = Character.toUpperCase(letter);
        if (upper == 'F') {
            return 0.0;
        }
        if (upper < 'A' || upper > 'D') {
            return -1.0;
        }
        return 4.0 - (upper - 'A');
    }
}
